/**
 * Mythological domain covers — public/figures/<key>-cover.webp.
 * Generated by scripts/domain-figures.py from public-domain Wikimedia
 * artwork (frescoes, mosaics, mythological paintings), graded warm with
 * an engraved plate frame. Keys may carry a sub-domain suffix
 * ("finance-crypto") — falls back to the parent domain's cover when no
 * dedicated artwork was generated.
 */

import { resolveCoverKey } from "./god-fields";
import { COVER_KEYS, COVER_META } from "./cover-manifest";

export type DomainFigureVariant = "cover";

function _coverKey(key: string | null | undefined): string | undefined {
  const ck = resolveCoverKey(key);
  if (!ck) return undefined;
  const k = COVER_KEYS.has(ck) ? ck : ck.split("-")[0];
  return COVER_KEYS.has(k) ? k : undefined;
}

/** URL of the mythological cover for a domain slug, vertical slug,
 * display name or free-form sub-domain topic. */
export function domainFigureUrl(
  key: string | null | undefined,
  _variant: DomainFigureVariant = "cover"
): string | undefined {
  const k = _coverKey(key);
  return k ? `/figures/${k}-cover.webp` : undefined;
}

export type PlateCover = { light: string; dark: string };

/** "sm" = AM-halftone plate — bold contrast that survives card-band
 * cropping. "" = stippled plate for heroes and frontispieces. */
export type PlateCoverVariant = "" | "-sm";

const NOMOS_PLATES: Record<PlateCoverVariant, PlateCover> = {
  "": { light: "/figures/nomos-plate-light.webp", dark: "/figures/nomos-plate-dark.webp" },
  "-sm": { light: "/figures/nomos-plate-sm-light.webp", dark: "/figures/nomos-plate-sm-dark.webp" },
};

/** The figureless field — universal fallback so every cover shares the
 * same plate treatment even when no domain resolves. */
export function nomosPlateCover(variant: PlateCoverVariant = ""): PlateCover {
  return NOMOS_PLATES[variant];
}

/** Light+dark URLs of the engraved-plate cover for a domain —
 * public/figures/<key>-plate{variant}-{light,dark}.webp, pre-rendered by
 * scripts/cover-plates.py (Voronoi stipple lg / AM halftone sm).
 * Sub-domains keep their own figure when one was generated. */
export function plateCoverUrl(
  key: string | null | undefined,
  variant: PlateCoverVariant = ""
): PlateCover | undefined {
  const k = _coverKey(key);
  return k
    ? {
        light: `/figures/${k}-plate${variant}-light.webp`,
        dark: `/figures/${k}-plate${variant}-dark.webp`,
      }
    : undefined;
}

/** Artwork credit for the resolved cover (title + artist/venue). */
export function domainCoverCredit(
  key: string | null | undefined
): { title: string; credit: string } | undefined {
  const k = _coverKey(key);
  return k ? COVER_META[k] : undefined;
}
